SELECT sr.id, sr.source_id AS sourceId, srd.source_detail_id AS sourceDetailId, srd.id as detailId, sr.create_time AS createTime, sr.code, sr.source_code AS sourceCode, sr.type, sr.approve_status AS approveStatus, sr.invalid_status AS invalidStatus, sr.customer_id AS customerId, sr.sales_org_id AS salesOrgId, sr.sales_org_name AS salesOrgName, sr.seller_id AS sellerId, sr.seller_name AS sellerName, srd.sku_id AS skuId, srd.sku_no AS skuNo, srd.sales_qty AS salesQty, srd.return_qty AS returnQty, sr.bill_date AS billDate, sr.approve_user_name AS approveUserName, sr.create_user_name AS createUserName FROM so_return_detail srd INNER JOIN so_return sr ON srd.main_id = sr.id AND srd.is_deleted = FALSE WHERE ${params.sqlMap.default} and sr.is_deleted=false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sr.create_time desc

SELECT sr.id, sr.source_id AS sourceId, srd.source_detail_id AS sourceDetailId, sr.create_time AS createTime, sr.code, sr.source_code AS sourceCode, sr.type, sr.approve_status AS approveStatus, sr.invalid_status AS invalidStatus, sr.customer_id AS customerId, sr.sales_org_id AS salesOrgId, sr.sales_org_name AS salesOrgName, sr.seller_id AS sellerId, sr.seller_name AS sellerName, srd.sku_id AS skuId, srd.sku_no AS skuNo, srd.sales_qty AS salesQty, srd.return_qty AS returnQty, sr.bill_date AS billDate, sr.approve_user_name AS approveUserName, sr.create_user_name AS createUserName FROM so_return_detail srd INNER JOIN so_return sr ON srd.main_id = sr.id AND srd.is_deleted = FALSE WHERE ${params.sqlMap.default} and sr.is_deleted=false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sr.create_time desc

SELECT srd.id, srd.main_id, sr.source_id, srd.source_detail_id, sr.source_code, sr.code, sr.customer_id, sr.customer_name, sr.warehouse_id, sr.inventory_org_id, srd.sku_id, srd.sku_no, srd.return_qty, srd.return_type_dict, srd.remark, srd.return_reason_dict FROM so_return_detail srd INNER JOIN so_return sr ON srd.main_id = sr.id AND srd.is_deleted = FALSE WHERE sr.is_deleted = FALSE
and sr.id in
#{id}
